import functools


def 报时(fn):
    @functools.wraps(fn)
    def 包装(*args, **kwargs):
        print("……开演")
        result = fn(*args, **kwargs)
        print("……收工")
        return result

    return 包装


@报时
def 加鱼干(a, b):
    return a + b


a = int(input())
b = int(input())
print(加鱼干(a, b))
print(加鱼干.__name__)
